def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= 700:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 20.0))

    slots = int(supply // WATER_REQ)
    total_agents = 1 + len(alive_opps)
    scarcity = total_agents - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    critical_me = (hp <= 3) or (no_water >= 2)
    stressed_me = (hp <= 5) or (no_water >= 1)

    if slots >= total_agents:
        base = 3.0
    elif slots >= len(alive_opps):
        base = 9.0
    elif slots == 1:
        base = 18.0
    else:
        base = 12.0

    if scarcity <= 0:
        bid = base
    elif critical_me:
        target = max(58.0, lowest_prev + 2.5)
        if highest_prev > 110:
            target = max(target, 72.0)
        bid = target
    elif stressed_me:
        target = max(28.0, min(55.0, lowest_prev + 1.5))
        if slots == 1:
            target = max(target, 42.0)
        bid = target
    else:
        if slots >= len(alive_opps):
            bid = 8.0
        elif highest_prev >= 120 and rich_opp >= 2:
            bid = 14.0
        elif urgent_opp >= 2:
            bid = 16.0
        else:
            bid = max(12.0, min(26.0, avg_prev * 0.22))

    if day >= 8 and hp <= 5:
        bid = max(bid, 36.0)
    if day >= 9 and no_water >= 1:
        bid = max(bid, 52.0)

    if budget < 40:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, DAILY_SALARY * 1.05)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        max_bid = max(yesterday_bids)
    else:
        avg_bid = 80.0
        max_bid = 100.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_bid + 5.0)

    if day_context['supply'] < 20:
        return min(my_status['budget'], max(avg_bid, 85.0))

    return min(my_status['budget'], avg_bid * 0.95)
